window.CARDS=window.CARDS||{};CARDS["story-v-y2v10.25-index"]=[{"i":"sc-amikura-mako-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ichinose-honami ayanokouji-kiyotaka amikura-mako","q":"amikura mako arrival at the gym and the exam questions arrives at the gym with ichinose during the first break after the survival and elimination exam and finds ayanokoji in the rest area looking at a red panda article   oh  that s a cute photo  it s a red panda  right   is that really the problem  these things garnered quite a buzz on the internet too  didn t they  light and needling  she takes the red panda photo as an opening  then doubts his not watching tv excuse instead of accepting it  the page repeats a clause    amikura expressed her doubt  perhaps my not watching tv excuse wasn t persuasive enough  amikura expressed her doubt    kept as printed  comes to the gym with her  gym acquaintance  teases him about the questions he missed","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p1-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p1-1\">Arrival at the gym and the exam questions<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1–2<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">Arrives at the gym with Ichinose during the first break after the survival and elimination exam and finds Ayanokōji in the rest area looking at a red-panda article.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Oh, that’s a cute photo. It’s a red panda, right?”<span class=\"pg\">p.1<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Is that really the problem? These things garnered quite a buzz on the internet too, didn’t they?”<span class=\"pg\">p.2<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Voice<\/span> Light and needling: she takes the red-panda photo as an opening, then doubts his not-watching-TV excuse instead of accepting it.<span class=\"pg\">p.1–2<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page repeats a clause — “Amikura expressed her doubt; perhaps my not-watching-TV excuse wasn’t persuasive enough, Amikura expressed her doubt.” — kept as printed.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Comes to the gym with her.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gym acquaintance; teases him about the questions he missed.<span class=\"pg\">p.1–2<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p2-1\">→ After: The change in Honami<\/button><\/div><\/article>"},{"i":"sc-asakura-mako-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"","w":"asakura-mako","q":"asakura mako no print  the mako here is amikura the name  asakura  never appears in the volume  the mako on these pages is amikura mako  a separate roster row  zero prints  no presence is claimed","h":"<article class=\"card\" id=\"sc-asakura-mako-y2v10_25-p1-1\"><h3><span class=\"ttl\"><a href=\"../../../people/asakura-mako.html#sc-asakura-mako-y2v10_25-p1-1\">No print; the Mako here is Amikura<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1–9<\/span><span class=\"by\">notes on <a href=\"../../../people/asakura-mako.html\">Asakura Mako<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The name “Asakura” never appears in the volume; the Mako on these pages is Amikura Mako, a separate roster row.<span class=\"pg\">p.1–9<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Zero prints; no presence is claimed.<span class=\"pg\">p.1–9<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"","w":"ayanokouji-atsuomi","q":"ayanokoji atsuomi the surname only  never the given name every occurrence of  ayanokoji  on these pages is kiyotaka s surname   atsuomi  never prints in the volume  zero genuine prints  no presence is claimed","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y2v10_25-p1-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y2v10_25-p1-1\">The surname only, never the given name<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1–9<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Every occurrence of “Ayanokōji” on these pages is Kiyotaka’s surname; “Atsuomi” never prints in the volume.<span class=\"pg\">p.1–9<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Zero genuine prints; no presence is claimed.<span class=\"pg\">p.1–9<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"action spoken","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the gym break and the red panda search the first break after the survival and elimination special exam  he goes to the gym without being told  trains alone  cools down in the rest area and searches a word on his phone  the article that comes up convinces him  he is still looking at its red panda photos when the two girls arrive  the word he searched is never printed  only amikura s notice of the red panda photo identifies the article  the greeting  good morning  ayanokoji kun  and his  morning  are untagged  both are listed in the volume s unattributed lines   morning  trains early and alone  and looks up an answer himself rather than asking","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p1-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p1-1\">The gym break and the red-panda search<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">The first break after the survival and elimination special exam; he goes to the gym without being told, trains alone, cools down in the rest area and searches a word on his phone.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Morning.”<span class=\"pg\">p.1<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> The article that comes up convinces him; he is still looking at its red-panda photos when the two girls arrive.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The word he searched is never printed; only Amikura’s notice of the red-panda photo identifies the article.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The greeting “Good morning, Ayanokōji-kun.” and his “Morning.” are untagged; both are listed in the volume’s unattributed lines.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Trains early and alone, and looks up an answer himself rather than asking.<span class=\"pg\">p.1<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p1-2\">→ After: Ichinose and Amikura arrive; the exam questions<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p1-2","v":"y2v10.25","y":2,"o":29,"k":"action spoken","w":"amikura-mako ichinose-honami ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ichinose and amikura arrive  the exam questions ichinose and amikura come to the gym together and find him in the rest area   oh  that s a cute photo  it s a red panda  right   yeah  i was just doing some research   is it related to the exam question  ayanokoji kun  you got it wrong  didn t you   i can t deny it  probably because i hardly ever watch tv   now that you mention it  you got the tapioca question wrong too  are you surprisingly ignorant of the world  the print announces that  amikura also seemed to understand and asked  but prints no question between that line and his answer   a dropped speech  kept as printed   honestly  i didn t think not liking tv would backfire like that  the print leaves this line untagged  it is his answer to the exam talk and is listed in the volume s unattributed lines   an unexpected weakness was discovered  huh  the exam questions on a red panda and tapioca expose gaps in general knowledge left by not watching television  akiyama calls ichinose to the counter over a paperwork mistake  she leaves  and he stays with amikura rather than leaving immediately  she reads his phone search as exam curiosity and teases him about the questions he missed  gym acquaintance  she doubts his excuse and he does not defend it","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p1-2\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p1-2\">Ichinose and Amikura arrive; the exam questions<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1–2<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Ichinose and Amikura come to the gym together and find him in the rest area.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Oh, that’s a cute photo. It’s a red panda, right?”<span class=\"pg\">p.1<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Yeah. I was just doing some research.”<span class=\"pg\">p.1<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Is it related to the exam question? Ayanokōji-kun, you got it wrong, didn’t you?”<span class=\"pg\">p.2<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I can’t deny it. Probably because I hardly ever watch TV.”<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now that you mention it, you got the tapioca question wrong too. Are you surprisingly ignorant of the world?”<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print announces that “Amikura also seemed to understand and asked” but prints no question between that line and his answer — a dropped speech, kept as printed.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Honestly, I didn’t think not liking TV would backfire like that.”<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print leaves this line untagged; it is his answer to the exam talk and is listed in the volume’s unattributed lines.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “An unexpected weakness was discovered, huh?”<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> The exam questions on a red panda and tapioca expose gaps in general knowledge left by not watching television.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Akiyama calls Ichinose to the counter over a paperwork mistake; she leaves, and he stays with Amikura rather than leaving immediately.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> She reads his phone search as exam curiosity and teases him about the questions he missed.<span class=\"pg\">p.1–2<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Gym acquaintance; she doubts his excuse and he does not defend it.<span class=\"pg\">p.1–2<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p1-1\">← Before: The gym break and the red-panda search<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p2-1\">→ After: Waiting with Amikura; the change in Ichinose<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"action spoken","w":"amikura-mako ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami the gym arrival and the exam teasing comes to the gym with amikura during the first break after the survival and elimination exam and greets ayanokoji in the rest area   good morning  ayanokoji kun  the print does not attach a speaker tag to the greeting  the next sentence names ichinose and amikura as the arrivals  recorded in the volume s unattributed list   is it related to the exam question  ayanokoji kun  you got it wrong  didn t you  the print leaves this line untagged  it follows  ichinose seemed to have some insight  and the next speech is explicitly  hearing ichinose s words   now that you mention it  you got the tapioca question wrong too  are you surprisingly ignorant of the world   an unexpected weakness was discovered  huh  reads his phone search as curiosity about the exam rather than embarrassment  and teases him about the missed questions with a laugh  akiyama calls her to the counter over a mistake in her paperwork  she leaves the rest area with akiyama  arrives with her  probes his exam mistakes  then leaves him alone with amikura","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v10_25-p1-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v10_25-p1-1\">The gym arrival and the exam teasing<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1–2<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Comes to the gym with Amikura during the first break after the survival and elimination exam and greets Ayanokōji in the rest area.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Good morning, Ayanokōji-kun.”<span class=\"pg\">p.1<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Is it related to the exam question? Ayanokōji-kun, you got it wrong, didn’t you?”<span class=\"pg\">p.2<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Now that you mention it, you got the tapioca question wrong too. Are you surprisingly ignorant of the world?”<span class=\"pg\">p.2<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The print does not attach a speaker tag to the greeting; the next sentence names Ichinose and Amikura as the arrivals. Recorded in the volume’s unattributed list.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print leaves this line untagged; it follows “Ichinose seemed to have some insight” and the next speech is explicitly “Hearing Ichinose’s words”.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “An unexpected weakness was discovered, huh?”<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Reads his phone search as curiosity about the exam rather than embarrassment, and teases him about the missed questions with a laugh.<span class=\"pg\">p.1–2<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Akiyama calls her to the counter over a mistake in her paperwork; she leaves the rest area with Akiyama.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Arrives with her.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Probes his exam mistakes, then leaves him alone with Amikura.<span class=\"pg\">p.1–2<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v10_25-p3-1\">→ After: The misdirected-message story: present only in the retelling<\/button><\/div><\/article>"},{"i":"sc-shibata-sou-y2v10_25-p1-1","v":"y2v10.25","y":2,"o":29,"k":"","w":"shibata-sou","q":"shibata so shibata sou mentioned in passing named in this volume  passing mentions on pages  none  passing mention only","h":"<article class=\"card\" id=\"sc-shibata-sou-y2v10_25-p1-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shibata-sou.html#sc-shibata-sou-y2v10_25-p1-1\">shibata-sou mentioned in passing<\/a><\/span><span class=\"meta\">Y2V10.25 · p.1–10<\/span><span class=\"by\">notes on <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: none.<span class=\"pg\">p.1<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.1<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-akiyama-y2v10_25-p2-1","v":"y2v10.25","y":2,"o":29,"k":"action","w":"ichinose-honami akiyama","q":"akiyama the gym staff member calls ichinose to the counter a member of the gym staff appears in the rest area and calls ichinose over about a mistake in the paperwork she filled out  asks ichinose to rewrite the form  the two head toward the counter  leaving ayanokoji and amikura alone  no line of hers is printed  the page reports only the paperwork problem and the summons  calls her away from the rest area over the form","h":"<article class=\"card\" id=\"sc-akiyama-y2v10_25-p2-1\"><h3><span class=\"ttl\"><a href=\"../../../people/akiyama.html#sc-akiyama-y2v10_25-p2-1\">The gym staff member calls Ichinose to the counter<\/a><\/span><span class=\"meta\">Y2V10.25 · p.2<\/span><span class=\"by\">notes on <a href=\"../../../people/akiyama.html\">Akiyama<\/a><\/span><\/h3><p class=\"setup\">A member of the gym staff appears in the rest area and calls Ichinose over about a mistake in the paperwork she filled out.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q action\">Asks Ichinose to rewrite the form; the two head toward the counter, leaving Ayanokōji and Amikura alone.<span class=\"pg\">p.2<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> No line of hers is printed; the page reports only the paperwork problem and the summons.<span class=\"pg\">p.2<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Calls her away from the rest area over the form.<span class=\"pg\">p.2<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p2-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako","q":"amikura mako the change in honami with ichinose called to the counter by akiyama over a paperwork mistake  she sits down beside ayanokoji and opens the subject of how ichinose has changed   honami chan s really changed  huh  it s like  unimaginable from a few months  ago  the line runs across the page break and the print leaves it untagged  the next speech tag comes on p 3 with  amikura began to speak  recorded in the volume s unattributed list   it was right after the second year deserted island exam ended  and the second semester had just started  i think   back then  honami chan seemed unstable  or rather  she was often lost in thought   right around that time  a little incident happened in the class  oh  but keep this story between us  okay  don t tell honami chan  treats the story as a confidence with responsibility attached  she asks for secrecy before she tells it","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p2-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p2-1\">The change in Honami<\/a><\/span><span class=\"meta\">Y2V10.25 · p.2–3<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">With Ichinose called to the counter by Akiyama over a paperwork mistake, she sits down beside Ayanokōji and opens the subject of how Ichinose has changed.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Honami-chan’s really changed, huh? It’s like, unimaginable from a few months… ago…”<span class=\"pg\">p.2<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “It was right after the second-year deserted island exam ended, and the second semester had just started, I think.”<span class=\"pg\">p.3<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Back then, Honami-chan seemed unstable, or rather, she was often lost in thought.”<span class=\"pg\">p.3<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The line runs across the page break and the print leaves it untagged; the next speech tag comes on p.3 with “Amikura began to speak”. Recorded in the volume’s unattributed list.<span class=\"pg\">p.2–3<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Right around that time, a little incident happened in the class… Oh, but keep this story between us, okay? Don’t tell Honami-chan.”<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Treats the story as a confidence with responsibility attached; she asks for secrecy before she tells it.<span class=\"pg\">p.3<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p1-1\">← Before: Arrival at the gym and the exam questions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p3-1\">→ After: The misdirected message<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p2-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako ayanokouji-kiyotaka","q":"ayanokoji kiyotaka waiting with amikura  the change in ichinose he sits down leaving one empty chair between them  and amikura opens the subject of how ichinose has changed   honami chan s really changed  huh  it s like  unimaginable from a few months  ago   is that so  the print leaves this reply untagged  it is his answer in the narration and is listed in the volume s unattributed lines  he thinks  a few months  is an exaggeration  the change amikura means is not about the recent exam   the deserted island exam  huh  he connects her account to the period after the second year deserted island exam  when ichinose confessed to him and he told her about kei  listens to her account without interrupting  his one word questions keep her talking","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p2-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p2-1\">Waiting with Amikura; the change in Ichinose<\/a><\/span><span class=\"meta\">Y2V10.25 · p.2–3<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He sits down leaving one empty chair between them, and Amikura opens the subject of how Ichinose has changed.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Honami-chan’s really changed, huh? It’s like, unimaginable from a few months… ago…”<span class=\"pg\">p.2<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Is that so?”<span class=\"pg\">p.3<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The deserted island exam, huh?”<span class=\"pg\">p.3<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The print leaves this reply untagged; it is his answer in the narration and is listed in the volume’s unattributed lines.<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He thinks “a few months” is an exaggeration: the change Amikura means is not about the recent exam.<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Backstory<\/span> He connects her account to the period after the second-year deserted island exam, when Ichinose confessed to him and he told her about Kei.<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Listens to her account without interrupting; his one-word questions keep her talking.<span class=\"pg\">p.2–3<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p1-2\">← Before: Ichinose and Amikura arrive; the exam questions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p3-1\">→ After: The misdirected message and the alphabet<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p3-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ishizaki-daichi ichinose-honami amikura-mako","q":"amikura mako the misdirected message explains the origin of the rumor  a message ichinose sent by mistake during an unstable spell after the deserted island exam   i didn t see the text myself  but i think it was something like   i want to calm down and talk  can we meet in person  taken out of context  it sounds quite meaningful  right   different class  but the problem lies in who she accidentally sent it to  that person was ishizaki kun  and during the break  he came to our class and boldly asked   what does this message mean  while showing the screen   honami chan was flustered but immediately corrected it  saying it was a misdirected message  ishizaki kun was convinced and went back to his class  but the difficulty was what followed  the fact that it was a missent message meant that she intended to send that important message to someone else  names him as the accidental recipient who carried the screen into ichinose s class  keeps her confidence and tells the story without blaming her for the mistake","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p3-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p3-1\">The misdirected message<\/a><\/span><span class=\"meta\">Y2V10.25 · p.3–4<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">Explains the origin of the rumor: a message Ichinose sent by mistake during an unstable spell after the deserted island exam.<\/p><p class=\"with\">with <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “I didn’t see the text myself, but I think it was something like, ‘I want to calm down and talk. Can we meet in person?’ Taken out of context, it sounds quite meaningful, right?”<span class=\"pg\">p.3<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Different class. But the problem lies in who she accidentally sent it to. That person was Ishizaki-kun, and during the break, he came to our class and boldly asked, ‘What does this message mean?’ while showing the screen.”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Honami-chan was flustered but immediately corrected it, saying it was a misdirected message. Ishizaki-kun was convinced and went back to his class, but the difficulty was what followed. The fact that it was a missent message…”<span class=\"pg\">p.4<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Honami-chan was flustered but immediately corrected it, saying it was a misdirected message. Ishizaki-kun was convinced and went back to his class, but the difficulty was what followed. The fact that it was a missent message meant that she intended to send that important message to someone else.”<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Names him as the accidental recipient who carried the screen into Ichinose’s class.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Keeps her confidence and tells the story without blaming her for the mistake.<span class=\"pg\">p.3–4<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p2-1\">← Before: The change in Honami<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p4-1\">→ After: The alphabet and the freeze<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p3-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako ishizaki-daichi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the misdirected message and the alphabet amikura tells the story of a message ichinose sent by mistake and the rumor that followed   different class  but the problem lies in who she accidentally sent it to  that person was ishizaki kun  and during the break  he came to our class and boldly asked   what does this message mean  while showing the screen   but why does that lead to me  named as the accidental recipient  he is not on page in this story  the contact list coincidence   his  a  beside ishizaki s  i    is amikura s explanation for why the class suspected him   we were watching over her for a while  but it gradually started to feel heavy  boys who didn t think it was you started to wonder if she was planning to confess to someone  the page prints an unlabelled first person inset on ichinose s dilemma  he does not comment on it and it is not assigned a speaker","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p3-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p3-1\">The misdirected message and the alphabet<\/a><\/span><span class=\"meta\">Y2V10.25 · p.3–5<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Amikura tells the story of a message Ichinose sent by mistake and the rumor that followed.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Different class. But the problem lies in who she accidentally sent it to. That person was Ishizaki-kun, and during the break, he came to our class and boldly asked, ‘What does this message mean?’ while showing the screen.”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “But why does that lead to me?”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “We were watching over her for a while, but it gradually started to feel heavy. Boys who didn’t think it was you started to wonder if she was planning to confess to someone.”<span class=\"pg\">p.5<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Named as the accidental recipient; he is not on-page in this story.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The contact-list coincidence — his “A” beside Ishizaki’s “I” — is Amikura’s explanation for why the class suspected him.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page prints an unlabelled first-person inset on Ichinose’s dilemma; he does not comment on it and it is not assigned a speaker.<span class=\"pg\">p.5<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p2-1\">← Before: Waiting with Amikura; the change in Ichinose<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p6-1\">→ After: The girls’ rescue and the thanks<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v10_25-p3-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako ishizaki-daichi ichinose-honami","q":"ichinose honami the misdirected message story  present only in the retelling the subject of amikura s account  she is not on page between leaving for the counter  p 2  and returning  p 8  amikura dates the change in her to the period right after the second year deserted island exam  when she seemed unstable and often lost in thought  the narration ties that instability to the confession she made to ayanokoji and his telling her about kei   that person was ishizaki kun  and during the break  he came to our class and boldly asked   what does this message mean  while showing the screen   honami chan was flustered but immediately corrected it  saying it was a misdirected message  the message she meant to send read  i want to calm down and talk  can we meet in person    amikura s reconstruction  printed inside her account  the page prints an unlabelled first person inset on her dilemma   even though i wandered into this myself  it feels like i ve approached a dead end  the inset is not attributed to a speaker by the print  her public composure fails when the matter concerns herself  she turns pale and cannot improvise an excuse  his open handling of her misdirected message starts the rumor","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v10_25-p3-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v10_25-p3-1\">The misdirected-message story: present only in the retelling<\/a><\/span><span class=\"meta\">Y2V10.25 · p.3–8<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “That person was Ishizaki-kun, and during the break, he came to our class and boldly asked, ‘What does this message mean?’ while showing the screen.”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Honami-chan was flustered but immediately corrected it, saying it was a misdirected message.”<span class=\"pg\">p.4<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> The subject of Amikura’s account; she is not on-page between leaving for the counter (p.2) and returning (p.8).<span class=\"pg\">p.3–8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Amikura dates the change in her to the period right after the second-year deserted island exam, when she seemed unstable and often lost in thought.<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Backstory<\/span> The narration ties that instability to the confession she made to Ayanokōji and his telling her about Kei.<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The message she meant to send read “I want to calm down and talk. Can we meet in person?” — Amikura’s reconstruction, printed inside her account.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page prints an unlabelled first-person inset on her dilemma: “Even though I wandered into this myself, it feels like I’ve approached a dead end.” The inset is not attributed to a speaker by the print.<span class=\"pg\">p.5<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her public composure fails when the matter concerns herself; she turns pale and cannot improvise an excuse.<span class=\"pg\">p.4–5<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> His open handling of her misdirected message starts the rumor.<span class=\"pg\">p.4<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v10_25-p1-1\">← Before: The gym arrival and the exam teasing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v10_25-p8-1\">→ After: The return and the messages<\/button><\/div><\/article>"},{"i":"sc-ishizaki-daichi-y2v10_25-p3-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako ichinose-honami ishizaki-daichi","q":"ishizaki daichi named in the misdirected message story named only in amikura s retelling of ichinose s misdirected message  he never appears on page in this story   different class  but the problem lies in who she accidentally sent it to  that person was ishizaki kun  and during the break  he came to our class and boldly asked   what does this message mean  while showing the screen  he was the accidental recipient  not the intended one  the message was meant for a girl in ichinose s class  the page says he asked openly and accepted her correction  receives her misdirected message and brings the screen to her class","h":"<article class=\"card\" id=\"sc-ishizaki-daichi-y2v10_25-p3-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishizaki-daichi.html#sc-ishizaki-daichi-y2v10_25-p3-1\">Named in the misdirected-message story<\/a><\/span><span class=\"meta\">Y2V10.25 · p.3–4<\/span><span class=\"by\">notes on <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Different class. But the problem lies in who she accidentally sent it to. That person was Ishizaki-kun, and during the break, he came to our class and boldly asked, ‘What does this message mean?’ while showing the screen.”<span class=\"pg\">p.4<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Named only in Amikura’s retelling of Ichinose’s misdirected message; he never appears on-page in this story.<span class=\"pg\">p.3–4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He was the accidental recipient, not the intended one: the message was meant for a girl in Ichinose’s class. The page says he asked openly and accepted her correction.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Receives her misdirected message and brings the screen to her class.<span class=\"pg\">p.4<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-karuizawa-kei-y2v10_25-p3-1","v":"y2v10.25","y":2,"o":29,"k":"","w":"karuizawa-kei","q":"karuizawa kei named in the narrator s backward glance named only as  kei  when ayanokoji recalls the period after the deserted island exam  she is not present in the story  the page s sentence is  that was when i received an unexpected confession from ichinose and told her about kei  the reference explains why ichinose seemed unstable to those around her  the story gives no scene with karuizawa","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y2v10_25-p3-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y2v10_25-p3-1\">Named in the narrator&#x27;s backward glance<\/a><\/span><span class=\"meta\">Y2V10.25 · p.3<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Named only as “Kei” when Ayanokōji recalls the period after the deserted island exam; she is not present in the story.<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page&#x27;s sentence is “That was when I received an unexpected confession from Ichinose and told her about Kei.”<span class=\"pg\">p.3<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The reference explains why Ichinose seemed unstable to those around her; the story gives no scene with Karuizawa.<span class=\"pg\">p.3<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p4-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ichinose-honami amikura-mako","q":"amikura mako the alphabet and the freeze lays out why the class settled on ayanokoji  the contact list s alphabetical order puts his  a  next to ishizaki s  i   you d understand if you saw it  right   well  that s limited to those with sharp intuition  the boys started making noise for a different reason  ayanokoji kun  maybe it s because your  a  and ishizakikun s  i  are close in the contact list  which is arranged in alphabetical order  there are other names close by  but you and honami chan are often seen together   ishizakikun  prints without a hyphen or space   kept as printed  a translator s note printed on the page explains the japanese gojuon ordering that places   and   together   honami chan is always bright and composed  but she gets quite flustered when it comes to matters concerning herself  maybe she couldn t come up with a good excuse at that time  and she turned pale with her eyes drawn to the floor   catching sight of the scene  from our point of view  it was very rare to see honami chan like that   we were watching over her for a while  but it gradually started to feel heavy  boys who didn t think it was you started to wonder if she was planning to confess to someone  reads her public composure as a mask that fails when the matter is personal  the page prints an unlabelled first person inset on ichinose s dilemma before amikura resumes  the inset is recorded in the volume notes  not attributed to a speaker","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p4-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p4-1\">The alphabet and the freeze<\/a><\/span><span class=\"meta\">Y2V10.25 · p.4–5<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">Lays out why the class settled on Ayanokōji: the contact list’s alphabetical order puts his “A” next to Ishizaki’s “I”.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “You’d understand if you saw it, right?”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Well, that’s limited to those with sharp intuition… The boys started making noise for a different reason. Ayanokōji-kun, maybe it’s because your ‘A’ and Ishizakikun’s ‘I’ are close in the contact list, which is arranged in…”<span class=\"pg\">p.4<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Honami-chan is always bright and composed, but she gets quite flustered when it comes to matters concerning herself. Maybe she couldn’t come up with a good excuse at that time, and she turned pale with her eyes drawn to the…”<span class=\"pg\">p.4<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Well, that’s limited to those with sharp intuition… The boys started making noise for a different reason. Ayanokōji-kun, maybe it’s because your ‘A’ and Ishizakikun’s ‘I’ are close in the contact list, which is arranged in alphabetical order. There are other names close by, but you and Honami-chan are often seen together…”<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Ishizakikun” prints without a hyphen or space — kept as printed.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> A translator’s note printed on the page explains the Japanese gojūon ordering that places あ and い together.<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Honami-chan is always bright and composed, but she gets quite flustered when it comes to matters concerning herself. Maybe she couldn’t come up with a good excuse at that time, and she turned pale with her eyes drawn to the floor.”<span class=\"pg\">p.4<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Catching sight of the scene, from our point of view, it was very rare to see Honami-chan like that.”<span class=\"pg\">p.5<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We were watching over her for a while, but it gradually started to feel heavy. Boys who didn’t think it was you started to wonder if she was planning to confess to someone.”<span class=\"pg\">p.5<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Reads her public composure as a mask that fails when the matter is personal.<span class=\"pg\">p.4–5<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The page prints an unlabelled first-person inset on Ichinose’s dilemma before Amikura resumes; the inset is recorded in the volume notes, not attributed to a speaker.<span class=\"pg\">p.5<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p3-1\">← Before: The misdirected message<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p6-1\">→ After: The girls’ rescue and the thanks<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p6-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako","q":"amikura mako the girls  rescue and the thanks describes how the girls closed ranks  they knew the intended recipient and protected her privacy   like me  the girls knew who honami chan intended to send it to  we secretly discussed how to help and stepped in to support her  the intended recipient was a girl who had sought love advice from ichinose  ichinose s silence protected that girl   there was nothing to do but accept it  right  the print leaves this line untagged  recorded in the volume s unattributed list   i didn t do anything special  ichinose just recovered with her own strength   thanking someone who did nothing  deflects credit for the rescue onto ichinose and the group rather than claiming a hand in it","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p6-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p6-1\">The girls’ rescue and the thanks<\/a><\/span><span class=\"meta\">Y2V10.25 · p.6–7<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">Describes how the girls closed ranks: they knew the intended recipient and protected her privacy.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Like me, the girls knew who Honami-chan intended to send it to. We secretly discussed how to help and stepped in to support her.”<span class=\"pg\">p.6<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “There was nothing to do but accept it, right?”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “I didn’t do anything special. Ichinose just recovered with her own strength.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The intended recipient was a girl who had sought love advice from Ichinose; Ichinose’s silence protected that girl.<span class=\"pg\">p.6<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print leaves this line untagged; recorded in the volume’s unattributed list.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Thanking someone who did nothing?”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deflects credit for the rescue onto Ichinose and the group rather than claiming a hand in it.<span class=\"pg\">p.6–7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p4-1\">← Before: The alphabet and the freeze<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p7-1\">→ After: The warning<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p6-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the girls  rescue and the thanks he asks how ichinose got through the predicament  amikura explains the girls  collective rescue   how did she get through that predicament   like me  the girls knew who honami chan intended to send it to  we secretly discussed how to help and stepped in to support her   there was nothing to do but accept it  right   yeah  the print leaves both half lines untagged at the page break  they are listed in the volume s unattributed lines   did you return honami chan back to normal   i didn t do anything special  ichinose just recovered with her own strength   i see  but still  thank you   i just assume you re being modest  that s why i m grateful  thanks her even after she denies doing anything  and says the truth of it does not matter to the thanks","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p6-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p6-1\">The girls’ rescue and the thanks<\/a><\/span><span class=\"meta\">Y2V10.25 · p.6–7<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">He asks how Ichinose got through the predicament; Amikura explains the girls’ collective rescue.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “How did she get through that predicament?”<span class=\"pg\">p.6<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “Like me, the girls knew who Honami-chan intended to send it to. We secretly discussed how to help and stepped in to support her.”<span class=\"pg\">p.6<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “There was nothing to do but accept it, right?”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Yeah.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print leaves both half-lines untagged at the page break; they are listed in the volume’s unattributed lines.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you return Honami-chan back to normal?”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I didn’t do anything special. Ichinose just recovered with her own strength.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see… but still, thank you.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I just assume you’re being modest. That’s why I’m grateful.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Thanks her even after she denies doing anything, and says the truth of it does not matter to the thanks.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p3-1\">← Before: The misdirected message and the alphabet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p7-1\">→ After: The warning and the terms<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p7-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami amikura-mako","q":"amikura mako the warning turns from the past to the present  she tells ayanokoji that ichinose still sees him as someone special and asks him not to hurt her   no  it s a different matter   you can tell if you look  but even now  honami chan sees you as someone very special  you re the only one in this school who can have a strong influence on her  that s why   i m telling you this because  i don t want you to make honami chan sad or hurt her   right   of course  i understand your position  it s not about whether you re dating or not  i just don t want her to be unnecessarily hurt   it s tough for honamichan  falling for a guy who has a girlfriend   honamichan  prints without a hyphen   kept as printed   i have a vague idea of you too  i figure you aren t flustered  right  reads him as unflustered and says so  asks him plainly not to hurt ichinose  her best friend  she can see ichinose s feelings and acts on them without speaking for her","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p7-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p7-1\">The warning<\/a><\/span><span class=\"meta\">Y2V10.25 · p.7<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">Turns from the past to the present: she tells Ayanokōji that Ichinose still sees him as someone special and asks him not to hurt her.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “No, it’s a different matter.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “You can tell if you look, but even now, Honami-chan sees you as someone very special. You’re the only one in this school who can have a strong influence on her, that’s why.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “I’m telling you this because… I don’t want you to make Honami-chan sad or hurt her.”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Right,”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, I understand your position. It’s not about whether you’re dating or not. I just don’t want her to be unnecessarily hurt.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s tough for Honamichan, falling for a guy who has a girlfriend.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Honamichan” prints without a hyphen — kept as printed.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have a vague idea of you too. I figure you aren’t flustered, right?”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reads him as unflustered and says so; asks him plainly not to hurt Ichinose.<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Her best friend; she can see Ichinose’s feelings and acts on them without speaking for her.<span class=\"pg\">p.7<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p6-1\">← Before: The girls’ rescue and the thanks<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p8-1\">→ After: The terms and the goodbye<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p7-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the warning and the terms amikura tells him ichinose still sees him as someone special and asks him not to hurt her   but why tell me this  because you thought i was the one who helped   i don t intend to hurt her intentionally  but that s quite a difficult request   you re pretty straightforward  aren t you   maybe   i understand what you want to say  i ll deal with it well   you can t just abandon her as a friend  it s not a bad thing  the print leaves this line untagged  it follows the narration that amikura did not press him and precedes  i showed my understanding  listed in the volume s unattributed lines  accepts her warning without promising an outcome  answers her bluntness with his own","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p7-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p7-1\">The warning and the terms<\/a><\/span><span class=\"meta\">Y2V10.25 · p.7–8<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Amikura tells him Ichinose still sees him as someone special and asks him not to hurt her.<\/p><p class=\"with\">with <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “But why tell me this? Because you thought I was the one who helped?”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I don’t intend to hurt her intentionally, but that’s quite a difficult request.”<span class=\"pg\">p.7<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You’re pretty straightforward, aren’t you?”<span class=\"pg\">p.7<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Maybe.”<span class=\"pg\">p.7<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand what you want to say. I’ll deal with it well.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can’t just abandon her as a friend. It’s not a bad thing.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The print leaves this line untagged; it follows the narration that Amikura did not press him and precedes “I showed my understanding”. Listed in the volume’s unattributed lines.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Accepts her warning without promising an outcome; answers her bluntness with his own.<span class=\"pg\">p.7–8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p6-1\">← Before: The girls’ rescue and the thanks<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p8-1\">→ After: Ichinose returns; the messages; the closing assessment<\/button><\/div><\/article>"},{"i":"sc-amikura-mako-y2v10_25-p8-1","v":"y2v10.25","y":2,"o":29,"k":"spoken","w":"amikura-mako","q":"amikura mako the terms and the goodbye accepts his answer without pressing  apologizes for speaking as a third party  and covers her embarrassment when ichinose returns   i m sorry  it s not my place to tell you this as a third party  the print leaves  sorry to keep you both waiting  and  no  not at all  untagged  the first follows  ichinose returned  the second follows the narration of amikura s momentary fluster  both are listed in the volume s unattributed lines   no  not at all  blunt but careful  she states the hard request  then immediately concedes she has no standing to make it  leaves the story as ichinose s best friend who has said her piece  no further scene","h":"<article class=\"card\" id=\"sc-amikura-mako-y2v10_25-p8-1\"><h3><span class=\"ttl\"><a href=\"../../../people/amikura-mako.html#sc-amikura-mako-y2v10_25-p8-1\">The terms and the goodbye<\/a><\/span><span class=\"meta\">Y2V10.25 · p.8–9<\/span><span class=\"by\">notes on <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/span><\/h3><p class=\"setup\">Accepts his answer without pressing, apologizes for speaking as a third party, and covers her embarrassment when Ichinose returns.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “I’m sorry, it’s not my place to tell you this as a third party.”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Amikura Mako<\/b> “No, not at all.”<span class=\"pg\">p.8<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The print leaves “Sorry to keep you both waiting,” and “No, not at all.” untagged; the first follows “Ichinose returned”, the second follows the narration of Amikura’s momentary fluster. Both are listed in the volume’s unattributed lines.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Voice<\/span> Blunt but careful: she states the hard request, then immediately concedes she has no standing to make it.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Leaves the story as Ichinose’s best friend who has said her piece; no further scene.<span class=\"pg\">p.9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-amikura-mako-y2v10_25-p7-1\">← Before: The warning<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y2v10_25-p8-1","v":"y2v10.25","y":2,"o":29,"k":"action inner spoken","w":"ichinose-honami ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ichinose returns  the messages  the closing assessment ichinose returns from the counter  he says goodbye and leaves the gym   sorry to keep you both waiting  the apology is untagged  it follows  ichinose returned  and is listed in the volume s unattributed lines   well then  i m going to head home soon  see you two later  outside  he receives a message from ichinose asking whether he and amikura were talking about her   were you having another private talk with mako chan  about me  the line is printed in square brackets as a phone message  not speech   looks like you ve got a good best friend  he answers with that line rather than disclosing the conversation  keeping his promise to amikura  ichinose replies with a stamp of the utmost happiness  he reads it and walks on   since the deserted island exam period  she has indeed changed a lot   ichinose honami  huh  frames her growth as a new insight into an analysis he had thought finished  not as a surprise  guesses the talk concerned her but does not ask  he deflects and she accepts the deflection","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y2v10_25-p8-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y2v10_25-p8-1\">Ichinose returns; the messages; the closing assessment<\/a><\/span><span class=\"meta\">Y2V10.25 · p.8–9<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Ichinose returns from the counter; he says goodbye and leaves the gym.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Sorry to keep you both waiting,”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Well then, I’m going to head home soon. See you two later.”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Were you having another private talk with Mako-chan? About me?”<span class=\"pg\">p.8<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The apology is untagged; it follows “Ichinose returned” and is listed in the volume’s unattributed lines.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Outside, he receives a message from Ichinose asking whether he and Amikura were talking about her.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The line is printed in square brackets as a phone message, not speech.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Looks like you’ve got a good best friend.”<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He answers with that line rather than disclosing the conversation, keeping his promise to Amikura.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Ichinose replies with a stamp of the utmost happiness; he reads it and walks on.<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> “Since the deserted island exam period, she has indeed changed a lot.”<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Inner voice<\/span> “‘Ichinose Honami,’ huh?”<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Frames her growth as a new insight into an analysis he had thought finished, not as a surprise.<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Guesses the talk concerned her but does not ask; he deflects and she accepts the deflection.<span class=\"pg\">p.8–9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y2v10_25-p7-1\">← Before: The warning and the terms<\/button><\/div><\/article>"},{"i":"sc-ichinose-honami-y2v10_25-p8-1","v":"y2v10.25","y":2,"o":29,"k":"action spoken","w":"ayanokouji-kiyotaka amikura-mako ichinose-honami","q":"ichinose honami the return and the messages returns from the counter and finds ayanokoji and amikura in the rest area  she does not ask what they discussed   sorry to keep you both waiting  the apology is untagged  it follows  ichinose returned  and is listed in the volume s unattributed lines   were you having another private talk with mako chan  about me  the line is printed in square brackets as a phone message  not speech   looks like you ve got a good best friend  replies to his message with a stamp of  the utmost happiness  checks on the conversation through amikura s interests rather than her own  then answers his deflection with a happy stamp instead of pressing  calls her  mako chan  trusts her enough not to interrogate her  guesses the talk concerned her and accepts his non answer","h":"<article class=\"card\" id=\"sc-ichinose-honami-y2v10_25-p8-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y2v10_25-p8-1\">The return and the messages<\/a><\/span><span class=\"meta\">Y2V10.25 · p.8–9<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Returns from the counter and finds Ayanokōji and Amikura in the rest area; she does not ask what they discussed.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Sorry to keep you both waiting,”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “Were you having another private talk with Mako-chan? About me?”<span class=\"pg\">p.8<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Looks like you’ve got a good best friend.”<span class=\"pg\">p.8<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The apology is untagged; it follows “Ichinose returned” and is listed in the volume’s unattributed lines.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The line is printed in square brackets as a phone message, not speech.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Replies to his message with a stamp of “the utmost happiness”.<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Checks on the conversation through Amikura’s interests rather than her own, then answers his deflection with a happy stamp instead of pressing.<span class=\"pg\">p.8–9<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Calls her “Mako-chan”; trusts her enough not to interrogate her.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Guesses the talk concerned her and accepts his non-answer.<span class=\"pg\">p.8–9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y2v10_25-p3-1\">← Before: The misdirected-message story: present only in the retelling<\/button><\/div><\/article>"}];
